package allocationcheck

import (
	escape "allocationcheck/escape"
	shapes "allocationcheck/shapes"
	value "allocationcheck/value"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"runtime"
	"testing"
	"time"
)

func TestConstructorsAndLifetime(t *testing.T) {
	for _, v := range []int{-7, 0, 1, 999} {
		t.Run(fmt.Sprint(v), func(t *testing.T) {
			if value.NewUserValue(v).ID != v || value.NewUser(v).ID != v || value.ReadID(v) != v || escape.ReadLocal(v) != v {
				t.Fatal("wrong result")
			}
			escape.SaveGlobal(v)
			runtime.GC()
			if escape.Saved == nil || *escape.Saved != v {
				t.Fatal("saved pointer did not retain value")
			}
		})
	}
	escape.Saved = nil
}
func TestSumBounds(t *testing.T) {
	for _, n := range []int{-1, 0, 1, 8, 32, 33, 1024, 1025} {
		t.Run(fmt.Sprint(n), func(t *testing.T) {
			got, ok := escape.Sum(n)
			if n < 0 || n > 1024 {
				if ok || got != 0 {
					t.Fatal(got, ok)
				}
				return
			}
			expected := 0
			for i := 0; i < n; i++ {
				expected += i % 256
			}
			if !ok || got != expected {
				t.Fatalf("got %d,%t want %d,true", got, ok, expected)
			}
		})
	}
}
func TestDescriptorAndArrayCopies(t *testing.T) {
	b := make([]byte, 64)
	b[0] = 7
	h := shapes.Holder{Bytes: b, Text: "hello"}
	copyH := h
	copyH.Bytes[0] = 9
	if h.Bytes[0] != 9 {
		t.Fatal("descriptor copy should share backing bytes")
	}
	var a shapes.Blob
	a[0] = 7
	copyA := a
	copyA[0] = 9
	if a[0] != 7 {
		t.Fatal("array value copy should be independent")
	}
	view := b[:16:16]
	clone := bytes.Clone(view)
	b[0] = 11
	if view[0] != 11 || clone[0] != 9 || cap(view) != 16 {
		t.Fatal("cap restriction is not a copy")
	}
}

type observation struct {
	Mode                                      string
	Before, Live, After, ScanBefore, ScanLive uint64
}

func TestReachabilityAndScanning(t *testing.T) {
	for _, mode := range []string{"bytes", "pointers", "interior"} {
		t.Run(mode, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 45*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, "go", "run", "./probe", mode)
			out, err := cmd.CombinedOutput()
			if err != nil {
				t.Fatalf("%v: %s", err, out)
			}
			var v observation
			if err := json.Unmarshal(out, &v); err != nil {
				t.Fatalf("%v: %s", err, out)
			}
			t.Log(string(out))
			if v.Live < v.Before+3<<20 || v.Live < v.After+3<<20 {
				t.Fatalf("expected retained then reclaimed allocation: %+v", v)
			}
			if mode == "pointers" {
				if v.ScanLive < v.ScanBefore+3<<20 {
					t.Fatal("pointer array should add scan work")
				}
			} else if v.ScanLive > v.ScanBefore+1<<20 {
				t.Fatal("byte array should not add multi-MiB pointer scanning")
			}
		})
	}
}

var result int

func BenchmarkValue(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		result = value.NewUserValue(i).ID
	}
}
func BenchmarkPointerLocal(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		result = value.ReadID(i)
	}
}
func BenchmarkReadLocal(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		result = escape.ReadLocal(i)
	}
}
func BenchmarkSaveGlobal(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		escape.SaveGlobal(i)
	}
	escape.Saved = nil
}
func BenchmarkSum(b *testing.B) {
	for _, n := range []int{8, 32, 33, 1024} {
		b.Run(fmt.Sprint(n), func(b *testing.B) {
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				result, _ = escape.Sum(n)
			}
		})
	}
}

fixtures.escape/example.go:
package example

var Saved *int

func makeInt(v int) *int  { return &v }
func retain(p *int)       { Saved = p }
func ReadLocal(v int) int { return *makeInt(v) }
func SaveGlobal(v int)    { retain(&v) }

func Sum(n int) (int, bool) {
	if n < 0 || n > 1024 {
		return 0, false
	}
	buf := make([]byte, n)
	for i := range buf {
		buf[i] = byte(i)
	}
	sum := 0
	for _, v := range buf {
		sum += int(v)
	}
	return sum, true
}

fixtures.probe/main.go:
package main

import (
	"encoding/json"
	"os"
	"runtime"
	"runtime/metrics"
	"unsafe"
)

var retained any

func sample() (uint64, uint64) {
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	s := []metrics.Sample{{Name: "/gc/scan/heap:bytes"}}
	metrics.Read(s)
	return m.HeapAlloc, s[0].Value.Uint64()
}
func main() {
	mode := os.Args[1]
	runtime.GC()
	before, scanBefore := sample()
	const size = 4 << 20
	switch mode {
	case "bytes":
		retained = make([]byte, size)
	case "pointers":
		retained = make([]*byte, size/int(unsafe.Sizeof((*byte)(nil))))
	case "interior":
		b := make([]byte, size)
		b[size/2] = 17
		retained = b[size/2 : size/2+16 : size/2+16]
	default:
		panic("invalid mode")
	}
	runtime.GC()
	live, scanLive := sample()
	runtime.KeepAlive(retained)
	retained = nil
	runtime.GC()
	after, _ := sample()
	out := struct {
		Mode                                      string
		Before, Live, After, ScanBefore, ScanLive uint64
	}{mode, before, live, after, scanBefore, scanLive}
	if err := json.NewEncoder(os.Stdout).Encode(out); err != nil {
		panic(err)
	}
}

